-- GERADO por `pnpm db:seed:gen` a partir de supabase/seed/questions/*.json. Não edite à mão.
insert into public.questions (slug, type, category, tags, difficulty, prompt, code, code_lang, options, correct, explanation, status) values
  ('ia-001', 'multiple_choice', 'IA', array['llm']::text[], 'facil', 'O que significa a sigla **LLM**?', null, null, '[{"id":"a","text":"Linear Learning Machine"},{"id":"b","text":"Large Language Model"},{"id":"c","text":"Low Latency Model"},{"id":"d","text":"Logical Language Module"}]'::jsonb, '["b"]'::jsonb, 'LLM é um Large Language Model: um modelo de linguagem treinado com grandes volumes de texto para prever o próximo token.', 'published'),
  ('ia-002', 'true_false', 'IA', array['tokens', 'llm']::text[], 'facil', 'Em LLMs, um token sempre corresponde a exatamente uma palavra.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["b"]'::jsonb, 'Um token pode ser uma palavra inteira, um pedaço de palavra, um sinal de pontuação ou um espaço. Palavras raras costumam virar vários tokens.', 'published'),
  ('ia-003', 'multiple_choice', 'IA', array['rag']::text[], 'facil', 'No **RAG** (Retrieval-Augmented Generation), o que acontece antes de o modelo gerar a resposta?', null, null, '[{"id":"a","text":"O modelo é treinado de novo com os documentos da empresa"},{"id":"b","text":"A resposta é buscada em um cache de respostas anteriores"},{"id":"c","text":"Trechos de documentos relevantes são buscados e adicionados ao contexto"},{"id":"d","text":"A temperatura é zerada para evitar erros"}]'::jsonb, '["c"]'::jsonb, 'No RAG, uma etapa de busca recupera trechos relevantes (geralmente por similaridade de embeddings) e os coloca no prompt, para o modelo responder com base neles.', 'published'),
  ('ia-004', 'multiple_choice', 'IA', array['embeddings']::text[], 'facil', 'O que é um **embedding**?', null, null, '[{"id":"a","text":"Um vetor de números que representa o significado de um texto, imagem ou outro dado"},{"id":"b","text":"Um arquivo compactado com os pesos do modelo"},{"id":"c","text":"Uma instrução escondida no prompt"},{"id":"d","text":"O modo de executar o modelo dentro do navegador"}]'::jsonb, '["a"]'::jsonb, 'Embeddings são vetores em que itens com significado parecido ficam próximos. Eles são a base da busca semântica e do RAG.', 'published'),
  ('ia-005', 'multiple_choice', 'IA', array['prompt-engineering']::text[], 'medio', '*Few-shot prompting* consiste em:', null, null, '[{"id":"a","text":"Pedir ao modelo uma resposta com poucas palavras"},{"id":"b","text":"Treinar o modelo com um dataset pequeno"},{"id":"c","text":"Fazer várias chamadas em paralelo e escolher a melhor"},{"id":"d","text":"Incluir no prompt alguns exemplos de entrada e da saída esperada"}]'::jsonb, '["d"]'::jsonb, 'No few-shot, o prompt traz alguns exemplos resolvidos para o modelo imitar o formato e o raciocínio. Não há treino: tudo acontece no contexto.', 'published'),
  ('ia-006', 'true_false', 'IA', array['temperatura', 'llm']::text[], 'medio', 'Aumentar a **temperatura** na amostragem tende a deixar as respostas mais variadas e menos determinísticas.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["a"]'::jsonb, 'A temperatura achata a distribuição de probabilidade dos próximos tokens. Valores altos dão mais chance a tokens menos prováveis; valores perto de 0 deixam a saída quase determinística.', 'published'),
  ('ia-007', 'multiple_choice', 'IA', array['contexto', 'tokens']::text[], 'medio', 'O que é a **janela de contexto** de um LLM?', null, null, '[{"id":"a","text":"A quantidade máxima de tokens que o modelo consegue considerar de uma vez"},{"id":"b","text":"O tempo máximo que uma chamada pode levar"},{"id":"c","text":"O número de usuários que podem usar o modelo ao mesmo tempo"},{"id":"d","text":"O tamanho do dataset usado no treinamento"}]'::jsonb, '["a"]'::jsonb, 'A janela de contexto limita quantos tokens (prompt, histórico, documentos e resposta) cabem em uma chamada. O que passa disso precisa ser cortado ou resumido.', 'published'),
  ('ia-008', 'multi_select', 'IA', array['rag', 'embeddings']::text[], 'medio', 'Quais destes componentes costumam fazer parte de um pipeline de RAG?', null, null, '[{"id":"a","text":"Divisão dos documentos em trechos (chunks)"},{"id":"b","text":"Geração de embeddings dos trechos"},{"id":"c","text":"Busca por similaridade em um índice vetorial"},{"id":"d","text":"Fine-tuning do modelo a cada pergunta recebida"}]'::jsonb, '["a","b","c"]'::jsonb, 'O RAG indexa os documentos (chunks + embeddings) e, a cada pergunta, busca os trechos mais similares. Ele não altera os pesos do modelo.', 'published'),
  ('ia-009', 'code_output', 'IA', array['embeddings', 'python']::text[], 'medio', 'Qual é a saída deste produto escalar entre dois embeddings?', 'a = [1, 0]
b = [0, 1]
dot = sum(x * y for x, y in zip(a, b))
print(dot)', 'python', '[{"id":"a","text":"1"},{"id":"b","text":"0"},{"id":"c","text":"2"},{"id":"d","text":"-1"}]'::jsonb, '["b"]'::jsonb, '1*0 + 0*1 = 0. Vetores ortogonais têm produto escalar 0, ou seja, nenhuma similaridade de direção.', 'published'),
  ('ia-010', 'multi_select', 'IA', array['agentes']::text[], 'medio', 'Quais destes são componentes típicos de um **agente** baseado em LLM?', null, null, '[{"id":"a","text":"Um compilador que transforma o prompt em código de máquina"},{"id":"b","text":"O modelo de linguagem, que decide o próximo passo"},{"id":"c","text":"Ferramentas que ele pode chamar, como APIs, busca ou execução de código"},{"id":"d","text":"Um loop que devolve o resultado das ferramentas para o contexto do modelo"}]'::jsonb, '["b","c","d"]'::jsonb, 'Um agente é um loop: o modelo escolhe uma ação (tool call), o sistema a executa e devolve o resultado, e o modelo decide o próximo passo até concluir a tarefa.', 'published'),
  ('ia-011', 'multiple_choice', 'IA', array['avaliacao', 'ml']::text[], 'medio', 'Em classificação, o que a métrica **precision** (precisão) mede?', null, null, '[{"id":"a","text":"Dos positivos reais, quantos o modelo encontrou"},{"id":"b","text":"Dos itens que o modelo previu como positivos, quantos realmente são positivos"},{"id":"c","text":"O percentual total de acertos, positivos e negativos"},{"id":"d","text":"A média harmônica entre duas outras métricas"}]'::jsonb, '["b"]'::jsonb, 'Precision = VP / (VP + FP). A alternativa A é o recall, a C é a accuracy e a D é o F1.', 'published'),
  ('ia-012', 'code_output', 'IA', array['contexto', 'tokens', 'python']::text[], 'medio', 'Para caber no contexto, o histórico é truncado assim. Qual é a saída?', 'tokens = ["Olá", ",", " mundo", "!"]
limite = 3
print(tokens[-limite:])', 'python', '[{"id":"a","text":"[''Olá'', '','', '' mundo'']"},{"id":"b","text":"[''!'']"},{"id":"c","text":"[''Olá'', '','', '' mundo'', ''!'']"},{"id":"d","text":"['','', '' mundo'', ''!'']"}]'::jsonb, '["d"]'::jsonb, 'O fatiamento `[-3:]` pega os 3 últimos elementos. É o jeito comum de manter só o trecho mais recente do histórico.', 'published'),
  ('ia-013', 'true_false', 'IA', array['alucinacao', 'llm']::text[], 'facil', '**Alucinação** é quando o modelo gera uma informação plausível, mas falsa ou sem fundamento.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["a"]'::jsonb, 'O modelo gera texto provável, não necessariamente verdadeiro. RAG com citação de fontes e validação das respostas ajudam a reduzir alucinações.', 'published'),
  ('ia-014', 'multiple_choice', 'IA', array['ml']::text[], 'facil', 'Qual destes é um exemplo de **aprendizado supervisionado**?', null, null, '[{"id":"a","text":"Agrupar clientes parecidos sem nenhum rótulo (clustering)"},{"id":"b","text":"Reduzir a dimensionalidade dos dados com PCA"},{"id":"c","text":"Um agente que aprende a jogar recebendo recompensas"},{"id":"d","text":"Classificar e-mails como spam a partir de exemplos já rotulados"}]'::jsonb, '["d"]'::jsonb, 'Supervisionado = aprender a partir de pares entrada → rótulo. Clustering e PCA são não supervisionados; recompensas são aprendizado por reforço.', 'published'),
  ('ia-015', 'multi_select', 'IA', array['prompt-injection', 'seguranca', 'agentes']::text[], 'dificil', 'Quais práticas ajudam a mitigar **prompt injection** em aplicações com LLM?', null, null, '[{"id":"a","text":"Tratar conteúdo externo (páginas, documentos, e-mails) como dado, não como instrução"},{"id":"b","text":"Dar às ferramentas do agente só as permissões mínimas necessárias"},{"id":"c","text":"Confiar que um system prompt bem escrito impede qualquer ataque"},{"id":"d","text":"Exigir confirmação humana antes de ações sensíveis"}]'::jsonb, '["a","b","d"]'::jsonb, 'Nenhum prompt é garantia de defesa. O que funciona é limitar o estrago: separar dado de instrução, menor privilégio e humano no loop para ações críticas.', 'published'),
  ('ia-016', 'multiple_choice', 'IA', array['embeddings']::text[], 'dificil', 'Por que a **similaridade de cosseno** é comum para comparar embeddings?', null, null, '[{"id":"a","text":"É a única métrica que funciona com números reais"},{"id":"b","text":"Considera só a direção dos vetores, não o comprimento"},{"id":"c","text":"É sempre mais rápida que o produto escalar"},{"id":"d","text":"Garante valores sempre entre 0 e 1"}]'::jsonb, '["b"]'::jsonb, 'O cosseno mede o ângulo entre os vetores, então dois textos com o mesmo sentido ficam próximos mesmo que os vetores tenham normas diferentes. O valor vai de -1 a 1.', 'published'),
  ('ia-017', 'true_false', 'IA', array['fine-tuning', 'rag']::text[], 'dificil', 'Fine-tuning costuma ser a melhor forma de fazer um LLM responder com base em documentos que mudam toda semana.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["b"]'::jsonb, 'Para conhecimento que muda com frequência, o RAG é mais barato e fica sempre atualizado. Fine-tuning é melhor para ensinar estilo, formato ou uma tarefa específica.', 'published'),
  ('ia-018', 'code_output', 'IA', array['softmax', 'python']::text[], 'dificil', 'Este código aplica softmax sobre logits. Qual é a saída?', 'import math

logits = [2.0, 1.0, 0.1]
exps = [math.exp(x) for x in logits]
probs = [e / sum(exps) for e in exps]
print(probs.index(max(probs)))', 'python', '[{"id":"a","text":"0"},{"id":"b","text":"1"},{"id":"c","text":"2"},{"id":"d","text":"2.0"}]'::jsonb, '["a"]'::jsonb, 'O softmax preserva a ordem dos logits: o maior logit (2.0, no índice 0) vira a maior probabilidade. O código imprime o índice, não o valor.', 'published'),
  ('ia-019', 'multiple_choice', 'IA', array['avaliacao', 'llm']::text[], 'dificil', 'O que é **contaminação de dados** (data contamination) na avaliação de LLMs?', null, null, '[{"id":"a","text":"Erros de rede que corrompem as respostas durante a avaliação"},{"id":"b","text":"Usuários enviarem dados pessoais nos prompts"},{"id":"c","text":"As perguntas do benchmark estarem nos dados de treino, inflando o resultado"},{"id":"d","text":"O modelo gerar conteúdo tóxico nas respostas"}]'::jsonb, '["c"]'::jsonb, 'Se o modelo viu as questões (ou as respostas) no treino, ele pode acertar por memorização. Por isso se usam benchmarks novos ou conjuntos de teste privados.', 'published'),
  ('ia-020', 'code_output', 'IA', array['prompt-engineering', 'python']::text[], 'facil', 'Um template de prompt é preenchido assim. Qual é a saída?', 'prompt = "Resuma: {texto}"
print(prompt.format(texto="RAG"))', 'python', '[{"id":"a","text":"Resuma: {texto}"},{"id":"b","text":"Resuma: texto"},{"id":"c","text":"Resuma: RAG"},{"id":"d","text":"KeyError: ''texto''"}]'::jsonb, '["c"]'::jsonb, '`str.format` troca `{texto}` pelo argumento nomeado `texto`. O KeyError só aconteceria se o argumento não fosse passado.', 'published'),
  ('prog-001', 'multiple_choice', 'PROGRAMACAO', array['sql']::text[], 'facil', 'Qual cláusula SQL filtra as linhas **antes** do agrupamento?', null, null, '[{"id":"a","text":"WHERE"},{"id":"b","text":"HAVING"},{"id":"c","text":"ORDER BY"},{"id":"d","text":"GROUP BY"}]'::jsonb, '["a"]'::jsonb, '`WHERE` filtra as linhas antes do `GROUP BY`; `HAVING` filtra os grupos já agregados, por isso pode usar `COUNT`, `SUM` etc.', 'published'),
  ('prog-002', 'code_output', 'PROGRAMACAO', array['python']::text[], 'facil', 'Qual é a saída?', 'nums = [3, 1, 2]
nums.sort()
print(nums)', 'python', '[{"id":"a","text":"[3, 1, 2]"},{"id":"b","text":"[1, 2, 3]"},{"id":"c","text":"None"},{"id":"d","text":"[3, 2, 1]"}]'::jsonb, '["b"]'::jsonb, '`list.sort()` ordena a lista no lugar (e retorna `None`). Como o código imprime `nums`, e não o retorno do `sort()`, sai a lista ordenada.', 'published'),
  ('prog-003', 'true_false', 'PROGRAMACAO', array['javascript']::text[], 'facil', 'Em JavaScript, `===` compara valor e tipo, sem conversão implícita.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["a"]'::jsonb, '`===` é a igualdade estrita: `1 === ''1''` é `false`. Já `==` converte os tipos antes de comparar, e `1 == ''1''` é `true`.', 'published'),
  ('prog-004', 'multiple_choice', 'PROGRAMACAO', array['estruturas-de-dados']::text[], 'facil', 'Qual estrutura segue a regra **LIFO** (o último a entrar é o primeiro a sair)?', null, null, '[{"id":"a","text":"Fila"},{"id":"b","text":"Árvore"},{"id":"c","text":"Pilha"},{"id":"d","text":"Tabela hash"}]'::jsonb, '["c"]'::jsonb, 'Na pilha (stack), `push` e `pop` acontecem no topo. A fila é FIFO: o primeiro a entrar é o primeiro a sair.', 'published'),
  ('prog-005', 'multiple_choice', 'PROGRAMACAO', array['testes']::text[], 'facil', 'O que é um **teste unitário**?', null, null, '[{"id":"a","text":"Um teste do sistema inteiro pela interface, como um usuário faria"},{"id":"b","text":"Um roteiro de teste executado manualmente"},{"id":"c","text":"Um teste de carga com muitos usuários simultâneos"},{"id":"d","text":"Um teste de uma pequena unidade de código, como uma função, de forma isolada"}]'::jsonb, '["d"]'::jsonb, 'Testes unitários são rápidos e isolados. A alternativa A descreve testes end-to-end, e a C, testes de carga.', 'published'),
  ('prog-006', 'code_output', 'PROGRAMACAO', array['javascript']::text[], 'medio', 'Qual é a saída no Node.js?', 'console.log([1, 2, 3].map((x) => x * 2).filter((x) => x > 2));', 'javascript', '[{"id":"a","text":"[ 2, 4, 6 ]"},{"id":"b","text":"[ 6 ]"},{"id":"c","text":"[ 4, 6 ]"},{"id":"d","text":"[ 1, 2, 3 ]"}]'::jsonb, '["c"]'::jsonb, 'O `map` gera `[2, 4, 6]` e o `filter` mantém só os maiores que 2: `[4, 6]`.', 'published'),
  ('prog-007', 'multiple_choice', 'PROGRAMACAO', array['sql']::text[], 'facil', 'Qual JOIN retorna todas as linhas da tabela da esquerda, mesmo sem correspondência na da direita?', null, null, '[{"id":"a","text":"INNER JOIN"},{"id":"b","text":"LEFT JOIN"},{"id":"c","text":"CROSS JOIN"},{"id":"d","text":"RIGHT JOIN"}]'::jsonb, '["b"]'::jsonb, 'O `LEFT JOIN` mantém todas as linhas da esquerda e preenche com `NULL` as colunas da direita quando não há correspondência.', 'published'),
  ('prog-008', 'true_false', 'PROGRAMACAO', array['java']::text[], 'medio', 'Em Java, comparar duas `String` com `==` compara o conteúdo delas.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["b"]'::jsonb, '`==` compara referências (se é o mesmo objeto). Para comparar o conteúdo, use `equals()`.', 'published'),
  ('prog-009', 'multi_select', 'PROGRAMACAO', array['typescript']::text[], 'medio', 'Quais destes são tipos utilitários nativos do TypeScript?', null, null, '[{"id":"a","text":"Partial<T>"},{"id":"b","text":"Pick<T, K>"},{"id":"c","text":"Nullable<T>"},{"id":"d","text":"Record<K, T>"}]'::jsonb, '["a","b","d"]'::jsonb, '`Partial`, `Pick` e `Record` vêm com o TypeScript. Não existe `Nullable` nativo; o que existe é `NonNullable<T>`, que faz o contrário.', 'published'),
  ('prog-010', 'multiple_choice', 'PROGRAMACAO', array['estruturas-de-dados', 'complexidade']::text[], 'medio', 'Qual é a complexidade **média** de uma busca por chave em uma tabela hash?', null, null, '[{"id":"a","text":"O(1)"},{"id":"b","text":"O(log n)"},{"id":"c","text":"O(n)"},{"id":"d","text":"O(n log n)"}]'::jsonb, '["a"]'::jsonb, 'O hash da chave aponta direto para o bucket, então a busca é O(1) em média. No pior caso, com muitas colisões, pode chegar a O(n).', 'published'),
  ('prog-011', 'code_output', 'PROGRAMACAO', array['python']::text[], 'dificil', 'Qual é a saída?', 'def add(item, lista=[]):
    lista.append(item)
    return lista

add(1)
print(add(2))', 'python', '[{"id":"a","text":"[2]"},{"id":"b","text":"[1]"},{"id":"c","text":"TypeError"},{"id":"d","text":"[1, 2]"}]'::jsonb, '["d"]'::jsonb, 'O valor padrão é criado uma única vez, quando a função é definida, e a mesma lista é compartilhada entre as chamadas. Use `lista=None` e crie a lista dentro da função.', 'published'),
  ('prog-012', 'multiple_choice', 'PROGRAMACAO', array['testes']::text[], 'medio', 'Para que serve um **mock** em testes?', null, null, '[{"id":"a","text":"Medir a cobertura de código"},{"id":"b","text":"Rodar os testes em paralelo"},{"id":"c","text":"Substituir uma dependência real (API, banco) por uma versão controlada, para isolar o que está sendo testado"},{"id":"d","text":"Gerar dados aleatórios para os testes"}]'::jsonb, '["c"]'::jsonb, 'Mocks simulam dependências e permitem verificar como elas foram chamadas, sem depender de rede, banco ou serviços externos.', 'published'),
  ('prog-013', 'code_output', 'PROGRAMACAO', array['javascript', 'ponto-flutuante']::text[], 'medio', 'Qual é a saída?', 'console.log(0.1 + 0.2 === 0.3);', 'javascript', '[{"id":"a","text":"true"},{"id":"b","text":"false"},{"id":"c","text":"undefined"},{"id":"d","text":"NaN"}]'::jsonb, '["b"]'::jsonb, 'Em ponto flutuante binário (IEEE 754), `0.1 + 0.2` dá `0.30000000000000004`. Compare com uma tolerância, como `Math.abs(a - b) < Number.EPSILON`.', 'published'),
  ('prog-014', 'multiple_choice', 'PROGRAMACAO', array['sql']::text[], 'dificil', 'Qual é a diferença entre `COUNT(*)` e `COUNT(coluna)`?', null, null, '[{"id":"a","text":"Nenhuma, os dois sempre retornam o mesmo valor"},{"id":"b","text":"`COUNT(coluna)` conta só os valores distintos"},{"id":"c","text":"`COUNT(*)` conta todas as linhas; `COUNT(coluna)` ignora as linhas em que a coluna é NULL"},{"id":"d","text":"`COUNT(*)` ignora as linhas com algum NULL"}]'::jsonb, '["c"]'::jsonb, '`COUNT(coluna)` conta os valores não nulos. Para contar distintos é preciso `COUNT(DISTINCT coluna)`.', 'published'),
  ('prog-015', 'multi_select', 'PROGRAMACAO', array['python']::text[], 'dificil', 'Quais destes valores podem ser **chaves** de um `dict` em Python?', null, null, '[{"id":"a","text":"(1, 2)  (tupla de inteiros)"},{"id":"b","text":"[1, 2]  (lista)"},{"id":"c","text":"\"id\"  (string)"},{"id":"d","text":"frozenset({1, 2})"}]'::jsonb, '["a","c","d"]'::jsonb, 'Chaves precisam ser hashable. Tuplas de imutáveis, strings e frozensets são; listas são mutáveis e não têm hash.', 'published'),
  ('prog-016', 'true_false', 'PROGRAMACAO', array['javascript']::text[], 'dificil', 'Em JavaScript, `typeof null` retorna `"object"`.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["a"]'::jsonb, 'É um bug histórico da linguagem, mantido por compatibilidade. Para testar nulo, use `valor === null`.', 'published'),
  ('prog-017', 'true_false', 'PROGRAMACAO', array['testes']::text[], 'facil', 'Ter 100% de cobertura de testes garante que o código não tem bugs.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["b"]'::jsonb, 'Cobertura diz quais linhas foram executadas, não se o comportamento foi verificado. Um teste sem asserções boas cobre o código e não pega nada.', 'published'),
  ('prog-018', 'multiple_choice', 'PROGRAMACAO', array['java']::text[], 'dificil', 'Em Java, o que acontece ao acessar um índice fora dos limites de um array?', null, null, '[{"id":"a","text":"Retorna `null`"},{"id":"b","text":"Lança `ArrayIndexOutOfBoundsException` em tempo de execução"},{"id":"c","text":"Retorna 0"},{"id":"d","text":"O código não compila"}]'::jsonb, '["b"]'::jsonb, 'O índice é verificado em tempo de execução. O compilador não consegue detectar isso em geral, porque o índice costuma vir de uma variável.', 'published'),
  ('prog-019', 'multiple_choice', 'PROGRAMACAO', array['typescript']::text[], 'medio', 'O que acontece com as anotações de tipo do TypeScript em tempo de execução?', null, null, '[{"id":"a","text":"São validadas automaticamente a cada chamada de função"},{"id":"b","text":"Deixam o código mais rápido"},{"id":"c","text":"Viram asserts no JavaScript gerado"},{"id":"d","text":"São removidas na compilação, e não há checagem de tipo em runtime"}]'::jsonb, '["d"]'::jsonb, 'Os tipos existem só na compilação. Para validar dados externos em runtime (como payloads de API), use uma biblioteca como o Zod.', 'published'),
  ('prog-020', 'multi_select', 'PROGRAMACAO', array['sql']::text[], 'medio', 'Quais destes comandos fazem parte da **DML** (manipulação de dados) do SQL?', null, null, '[{"id":"a","text":"INSERT"},{"id":"b","text":"CREATE TABLE"},{"id":"c","text":"UPDATE"},{"id":"d","text":"DELETE"}]'::jsonb, '["a","c","d"]'::jsonb, 'DML manipula os dados das tabelas (`INSERT`, `UPDATE`, `DELETE`). `CREATE TABLE` é DDL, que define a estrutura.', 'published'),
  ('wf-001', 'multiple_choice', 'WORKFLOW', array['git']::text[], 'facil', 'Qual comando cria um novo branch e já muda para ele?', null, null, '[{"id":"a","text":"git branch -d nome"},{"id":"b","text":"git switch -c nome"},{"id":"c","text":"git merge nome"},{"id":"d","text":"git push nome"}]'::jsonb, '["b"]'::jsonb, '`git switch -c nome` (ou o antigo `git checkout -b nome`) cria o branch e muda para ele. `git branch -d` apaga um branch.', 'published'),
  ('wf-002', 'true_false', 'WORKFLOW', array['git']::text[], 'facil', 'Por padrão, `git pull` equivale a `git fetch` seguido da integração das mudanças remotas no branch atual.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["a"]'::jsonb, 'O `pull` baixa os commits (`fetch`) e os integra ao branch atual, com merge por padrão ou rebase se configurado (`pull.rebase`).', 'published'),
  ('wf-003', 'multiple_choice', 'WORKFLOW', array['docker']::text[], 'facil', 'Qual é a diferença entre **imagem** e **contêiner** no Docker?', null, null, '[{"id":"a","text":"A imagem é o modelo imutável; o contêiner é uma instância em execução dela"},{"id":"b","text":"São sinônimos"},{"id":"c","text":"O contêiner é o arquivo Dockerfile; a imagem é o processo"},{"id":"d","text":"A imagem só existe no Docker Hub; o contêiner só existe localmente"}]'::jsonb, '["a"]'::jsonb, 'Uma imagem é um conjunto de camadas somente leitura. Cada `docker run` cria um contêiner a partir dela, com uma camada gravável própria.', 'published'),
  ('wf-004', 'multi_select', 'WORKFLOW', array['linux', 'shell']::text[], 'facil', 'Quais destes comandos mostram o conteúdo de um arquivo de texto no terminal?', null, null, '[{"id":"a","text":"cat"},{"id":"b","text":"less"},{"id":"c","text":"mkdir"},{"id":"d","text":"head"}]'::jsonb, '["a","b","d"]'::jsonb, '`cat` imprime o arquivo inteiro, `less` abre um paginador e `head` mostra as primeiras linhas. `mkdir` cria diretórios.', 'published'),
  ('wf-005', 'multiple_choice', 'WORKFLOW', array['ci-cd']::text[], 'facil', 'O que é **Integração Contínua** (CI)?', null, null, '[{"id":"a","text":"Fazer deploy manual em produção uma vez por mês"},{"id":"b","text":"Manter dois bancos de dados sincronizados"},{"id":"c","text":"Revisar todo o código só no fim do projeto"},{"id":"d","text":"Integrar mudanças ao repositório com frequência, com build e testes automáticos a cada envio"}]'::jsonb, '["d"]'::jsonb, 'Na CI, cada push ou PR dispara build e testes automaticamente, para detectar problemas de integração cedo. O deploy automático é a parte de CD.', 'published'),
  ('wf-006', 'true_false', 'WORKFLOW', array['docker']::text[], 'facil', 'Dados gravados no sistema de arquivos de um contêiner, sem volume, são perdidos quando o contêiner é removido.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["a"]'::jsonb, 'A camada gravável pertence ao contêiner e some com o `docker rm`. Para persistir dados, use volumes ou bind mounts.', 'published'),
  ('wf-007', 'code_output', 'WORKFLOW', array['shell', 'linux']::text[], 'medio', 'Qual é a saída deste comando?', 'echo "a b c" | wc -w', 'bash', '[{"id":"a","text":"1"},{"id":"b","text":"3"},{"id":"c","text":"5"},{"id":"d","text":"a b c"}]'::jsonb, '["b"]'::jsonb, 'O pipe manda a saída do `echo` para o `wc -w`, que conta palavras: `a`, `b` e `c`.', 'published'),
  ('wf-008', 'multiple_choice', 'WORKFLOW', array['git']::text[], 'medio', 'Qual é a principal diferença entre `git merge` e `git rebase` ao integrar um branch?', null, null, '[{"id":"a","text":"Nenhuma: os dois produzem exatamente o mesmo histórico"},{"id":"b","text":"O merge apaga o branch de origem; o rebase o mantém"},{"id":"c","text":"O rebase reaplica os commits sobre a nova base, deixando o histórico linear; o merge preserva o histórico com um commit de merge"},{"id":"d","text":"O rebase só funciona em repositórios remotos"}]'::jsonb, '["c"]'::jsonb, 'O rebase reescreve os commits (novos hashes), por isso não se faz rebase de commits já compartilhados. O merge não reescreve nada.', 'published'),
  ('wf-009', 'multi_select', 'WORKFLOW', array['docker']::text[], 'medio', 'Quais práticas reduzem o tamanho de uma imagem Docker?', null, null, '[{"id":"a","text":"Instalar ferramentas de debug na imagem final"},{"id":"b","text":"Multi-stage build, copiando só os artefatos finais para a última etapa"},{"id":"c","text":"Usar uma imagem base enxuta, como as variantes `-slim` ou `alpine`"},{"id":"d","text":"Usar `.dockerignore` para não copiar arquivos desnecessários"}]'::jsonb, '["b","c","d"]'::jsonb, 'Multi-stage deixa compiladores e dependências de build para trás, a base enxuta tem menos pacotes e o `.dockerignore` evita que `COPY .` leve lixo (node_modules, .git) para a imagem.', 'published'),
  ('wf-010', 'multiple_choice', 'WORKFLOW', array['airflow']::text[], 'medio', 'No Apache Airflow, o que é um **DAG**?', null, null, '[{"id":"a","text":"Um grafo acíclico dirigido que define as tarefas e as dependências entre elas"},{"id":"b","text":"O banco de dados de metadados do Airflow"},{"id":"c","text":"Um operador que executa SQL"},{"id":"d","text":"O log de execução de uma tarefa"}]'::jsonb, '["a"]'::jsonb, 'DAG = Directed Acyclic Graph. Ele descreve o que rodar e em que ordem; por ser acíclico, nenhuma tarefa depende de si mesma.', 'published'),
  ('wf-011', 'multiple_choice', 'WORKFLOW', array['kafka']::text[], 'medio', 'Que garantia de ordem de mensagens o **Kafka** oferece?', null, null, '[{"id":"a","text":"Ordem global em todo o tópico"},{"id":"b","text":"Ordem dentro de cada partição, mas não entre partições"},{"id":"c","text":"Ordem só dentro de cada consumer group"},{"id":"d","text":"Nenhuma garantia de ordem"}]'::jsonb, '["b"]'::jsonb, 'Cada partição é um log ordenado. Para manter a ordem de eventos relacionados (ex.: de um mesmo pedido), use a mesma chave, que leva à mesma partição.', 'published'),
  ('wf-012', 'code_output', 'WORKFLOW', array['git', 'shell']::text[], 'medio', 'Qual é a saída da última linha?', 'git init -q demo && cd demo
git commit -q --allow-empty -m "um"
git commit -q --allow-empty -m "dois"
git log --oneline | wc -l', 'bash', '[{"id":"a","text":"0"},{"id":"b","text":"1"},{"id":"c","text":"2"},{"id":"d","text":"3"}]'::jsonb, '["c"]'::jsonb, '`--allow-empty` permite criar commits sem mudanças. São dois commits, e `git log --oneline` imprime uma linha por commit.', 'published'),
  ('wf-013', 'true_false', 'WORKFLOW', array['ci-cd', 'github-actions']::text[], 'medio', 'No GitHub Actions, os jobs de um mesmo workflow rodam em sequência por padrão.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["b"]'::jsonb, 'Os jobs rodam em paralelo por padrão. Para criar dependência entre eles, use `needs:`.', 'published'),
  ('wf-014', 'multiple_choice', 'WORKFLOW', array['n8n', 'automacao']::text[], 'medio', 'No **n8n**, o que inicia a execução automática de um workflow?', null, null, '[{"id":"a","text":"O último nó do workflow"},{"id":"b","text":"Nada: só dá para executar manualmente pelo editor"},{"id":"c","text":"Um commit no repositório Git do workflow"},{"id":"d","text":"Um nó de gatilho (trigger), como Webhook, Schedule ou um evento de app"}]'::jsonb, '["d"]'::jsonb, 'Todo workflow ativo começa por um nó trigger, que dispara a execução quando chega uma requisição, quando o horário bate ou quando um app emite um evento.', 'published'),
  ('wf-015', 'code_output', 'WORKFLOW', array['shell', 'bash']::text[], 'dificil', 'Qual é a saída deste script bash?', 'x=1
(x=2)
echo $x', 'bash', '[{"id":"a","text":"1"},{"id":"b","text":"2"},{"id":"c","text":"Uma linha vazia"},{"id":"d","text":"Erro de sintaxe"}]'::jsonb, '["a"]'::jsonb, 'Os parênteses rodam o comando em um subshell. A atribuição `x=2` vale só dentro dele e não afeta o shell pai.', 'published'),
  ('wf-016', 'multi_select', 'WORKFLOW', array['kafka']::text[], 'dificil', 'Sobre **consumer groups** no Kafka, quais afirmações são verdadeiras?', null, null, '[{"id":"a","text":"Cada partição é lida por no máximo um consumidor do mesmo grupo"},{"id":"b","text":"Uma mensagem lida por um grupo é apagada do tópico para os outros grupos"},{"id":"c","text":"Grupos diferentes podem ler o mesmo tópico de forma independente"},{"id":"d","text":"Com mais consumidores do que partições, os consumidores excedentes ficam ociosos"}]'::jsonb, '["a","c","d"]'::jsonb, 'Cada grupo guarda seus próprios offsets, e as mensagens ficam no tópico até a retenção expirar, independentemente de quem leu. O paralelismo de um grupo é limitado pelo número de partições.', 'published'),
  ('wf-017', 'multiple_choice', 'WORKFLOW', array['airflow']::text[], 'dificil', 'No Airflow, o que acontece com um DAG com `catchup=True` e `start_date` no passado ao ser ativado?', null, null, '[{"id":"a","text":"As tarefas que falharam no passado são executadas de novo"},{"id":"b","text":"O scheduler cria execuções para todos os intervalos desde o `start_date` que ainda não rodaram"},{"id":"c","text":"O DAG passa a rodar só manualmente"},{"id":"d","text":"O DAG ignora o `schedule` e roda uma única vez"}]'::jsonb, '["b"]'::jsonb, 'Com catchup, o Airflow faz o backfill de cada intervalo perdido. Se isso não for desejado, use `catchup=False`.', 'published'),
  ('wf-018', 'multiple_choice', 'WORKFLOW', array['git']::text[], 'dificil', 'O que `git reset --hard HEAD~1` faz?', null, null, '[{"id":"a","text":"Cria um novo commit que desfaz o último (como o `git revert`)"},{"id":"b","text":"Só tira os arquivos do stage, sem mexer nos commits"},{"id":"c","text":"Apaga o branch remoto"},{"id":"d","text":"Move o branch para o commit anterior e descarta o último commit e as mudanças não commitadas"}]'::jsonb, '["d"]'::jsonb, '`--hard` move o branch e sobrescreve o índice e o diretório de trabalho. O commit ainda pode ser recuperado pelo `git reflog` por um tempo; mudanças não commitadas, não.', 'published'),
  ('wf-019', 'true_false', 'WORKFLOW', array['docker']::text[], 'dificil', 'Em um Dockerfile, a instrução `EXPOSE 3000` publica automaticamente a porta 3000 no host.', null, null, '[{"id":"a","text":"Verdadeiro"},{"id":"b","text":"Falso"}]'::jsonb, '["b"]'::jsonb, '`EXPOSE` só documenta a porta que a aplicação usa. Para publicar no host é preciso `-p 3000:3000` no `docker run` ou `ports:` no compose.', 'published'),
  ('wf-020', 'code_output', 'WORKFLOW', array['shell', 'linux']::text[], 'facil', 'Qual é a saída da última linha?', 'mkdir -p logs && touch logs/a.log logs/b.log logs/c.txt
ls logs/*.log | wc -l', 'bash', '[{"id":"a","text":"1"},{"id":"b","text":"3"},{"id":"c","text":"2"},{"id":"d","text":"0"}]'::jsonb, '["c"]'::jsonb, 'O glob `*.log` casa com `a.log` e `b.log`, mas não com `c.txt`. O `wc -l` conta as 2 linhas da saída do `ls`.', 'published')
on conflict (slug) do update set
  type = excluded.type,
  category = excluded.category,
  tags = excluded.tags,
  difficulty = excluded.difficulty,
  prompt = excluded.prompt,
  code = excluded.code,
  code_lang = excluded.code_lang,
  options = excluded.options,
  correct = excluded.correct,
  explanation = excluded.explanation;
